"use client";

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { IconMorph, type IconMorphPaths } from "../icon-morph/icon-morph";
import { motionTokens } from "../lib/motion-tokens";
import { MorphingText } from "../morphing-text/morphing-text";
import "../foundation.css";

export type ButtonVariant = "filled" | "bordered" | "text";
export type ButtonTone = "primary" | "secondary" | "success" | "warning" | "danger";
export type ButtonSize = "small" | "medium" | "large";

const baseClass = "inline-flex w-fit items-center justify-center gap-2 whitespace-nowrap rounded-[18px] border font-[inherit] font-[650] leading-none no-underline transition-[opacity,background-color,border-color,color,transform] duration-[var(--duration-fast)] ease-[var(--ease-standard)] [webkit-tap-highlight-color:transparent] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-3 disabled:cursor-not-allowed disabled:opacity-[0.48] aria-disabled:cursor-not-allowed aria-disabled:opacity-[0.48] active:not-disabled:translate-y-px";

const sizeClasses: Record<ButtonSize, string> = {
  small: "min-h-10 px-4 text-xs",
  medium: "min-h-[46px] px-5 text-[13px]",
  large: "min-h-[52px] px-6 text-sm",
};

const appearanceClasses: Record<ButtonVariant, Record<ButtonTone, string>> = {
  filled: {
    primary: "border-transparent bg-[var(--primary)] text-[var(--primary-foreground)] hover:bg-[var(--primary-hover)]",
    secondary: "border-transparent bg-[var(--surface-muted)] text-[var(--text)] hover:bg-[color-mix(in_srgb,var(--surface-muted)_82%,var(--text))]",
    success: "border-transparent bg-[var(--surface-muted)] text-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-transparent bg-[var(--surface-muted)] text-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-transparent bg-[var(--surface-muted)] text-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  bordered: {
    primary: "border-[color-mix(in_srgb,var(--text)_75%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text)] hover:border-[var(--text)] hover:bg-[color-mix(in_srgb,var(--primary)_25%,transparent)]",
    secondary: "border-[color-mix(in_srgb,var(--text-secondary)_72%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text-secondary)] hover:border-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--success-surface-foreground)] hover:border-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--warning-surface-foreground)] hover:border-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--danger-surface-foreground)] hover:border-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  text: {
    primary: "border-transparent bg-transparent text-[var(--text)] hover:bg-[var(--surface-muted)]",
    secondary: "border-transparent bg-transparent text-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-transparent bg-transparent text-[var(--success-surface-foreground)] hover:bg-[var(--surface-muted)]",
    warning: "border-transparent bg-transparent text-[var(--warning-surface-foreground)] hover:bg-[var(--surface-muted)]",
    danger: "border-transparent bg-transparent text-[var(--danger-surface-foreground)] hover:bg-[var(--surface-muted)]",
  },
};

function classes(variant: ButtonVariant, tone: ButtonTone, size: ButtonSize, className?: string) {
  return [baseClass, sizeClasses[size], appearanceClasses[variant][tone], className]
    .filter(Boolean)
    .join(" ");
}

interface ButtonStyleProps {
  variant?: ButtonVariant;
  tone?: ButtonTone;
  size?: ButtonSize;
}

type OneOrMany<Value> = Value | readonly Value[];

export interface ButtonProps
  extends Omit<ComponentPropsWithoutRef<"button">, "children"> {
  variant?: ButtonVariant;
  tone?: OneOrMany<ButtonTone>;
  size?: ButtonSize;
  children?: ReactNode;
  label?: OneOrMany<string>;
  icon?: OneOrMany<ReactNode>;
  iconPosition?: "start" | "end";
  loading?: OneOrMany<boolean>;
  state?: number;
  iconPaths?: IconMorphPaths;
}

function atState<Value>(value: OneOrMany<Value> | undefined, state: number) {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) return value as Value;
  return value[Math.min(state, value.length - 1)];
}

function ButtonIcon({ icons, state, paths, spinning }: {
  icons: OneOrMany<ReactNode>;
  state: number;
  paths?: IconMorphPaths;
  spinning?: boolean;
}) {
  const reduceMotion = useReducedMotion() ?? false;
  const values = Array.isArray(icons) ? icons : [icons];
  const current = values[Math.min(state, values.length - 1)];

  if (paths && values.length === 2) {
    return <IconMorph state={state > 0} from={values[0]} to={values[1]} paths={paths} size={18} />;
  }

  return (
    <span className="relative inline-grid size-[18px] place-items-center">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          className="absolute inset-0 grid origin-center place-items-center"
          key={state}
          initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
        >
          <motion.span
            className="grid place-items-center [&>svg]:size-[18px]"
            animate={{ rotate: spinning && !reduceMotion ? 360 : 0 }}
            transition={spinning && !reduceMotion
              ? { duration: 0.8, ease: "linear", repeat: Infinity }
              : { duration: 0 }}
          >
            {current}
          </motion.span>
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button({
  variant = "filled",
  tone = "primary",
  size = "medium",
  label,
  icon,
  iconPosition = "start",
  loading = false,
  state = 0,
  iconPaths,
  className,
  children,
  type = "button",
  ...props
}, ref) {
  const activeState = Math.max(0, Math.floor(state));
  const activeTone = atState(tone, activeState) ?? "primary";
  const isLoading = atState(loading, activeState) ?? false;
  const activeIcon = icon
    ? <ButtonIcon icons={icon} state={activeState} paths={iconPaths} spinning={isLoading} />
    : undefined;
  const content = label === undefined
    ? children
    : <MorphingText value={atState(label, activeState) ?? ""} />;
  const iconOnly = activeIcon !== undefined && content == null;

  return (
    <button
      ref={ref}
      {...props}
      type={type}
      aria-busy={isLoading || undefined}
      className={classes(variant, activeTone, size, [
        iconOnly && { small: "w-10 px-0", medium: "w-[46px] px-0", large: "w-[52px] px-0" }[size],
        className,
      ].filter(Boolean).join(" "))}
    >
      {activeIcon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
      {content}
      {activeIcon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
    </button>
  );
});

export interface ButtonLinkProps extends ComponentPropsWithoutRef<"a">, ButtonStyleProps {
  icon?: ReactNode;
  iconPosition?: "start" | "end";
}

export function ButtonLink({
  variant = "filled",
  tone = "primary",
  size = "medium",
  icon,
  iconPosition = "start",
  className,
  children,
  ...props
}: ButtonLinkProps) {
  return (
    <a {...props} className={classes(variant, tone, size, className)}>
      {icon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
      {children}
      {icon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
    </a>
  );
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  type ComponentType,
  type ReactNode,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { ChevronRight } from "lucide-react";
import {
  AnimatePresence,
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
} from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface SidebarNavigationItem {
  href?: string;
  label: string;
  /** Optional count displayed beside a parent item. Zero is displayed. */
  count?: number;
  children?: SidebarNavigationItem[];
  defaultExpanded?: boolean;
}

export interface SidebarNavigationGroup {
  label: string;
  /** Optional total displayed beside the group heading. Zero is displayed. */
  count?: number;
  items: SidebarNavigationItem[];
  defaultExpanded?: boolean;
}

export interface SidebarNavigationLinkProps {
  href: string;
  className?: string;
  "aria-current"?: "page";
  onClick?: () => void;
  onPointerEnter?: (event: React.PointerEvent<HTMLAnchorElement>) => void;
  children: ReactNode;
}

export interface SidebarNavigationProps {
  groups: SidebarNavigationGroup[];
  activeHref?: string;
  ariaLabel?: string;
  onActiveHrefChange?: (href: string) => void;
  /** Custom link component, e.g. `next/link` or React Router's `Link`. Defaults to `<a>`. */
  renderLink?: ComponentType<SidebarNavigationLinkProps>;
}

interface VisibleItem {
  item: SidebarNavigationItem;
  id: string;
  depth: number;
}

const rowHeight = 35;
const still = { duration: 0 } as const;
const parentButtonClass = "relative my-px flex h-[33px] w-full min-w-0 items-center justify-between border-0 bg-transparent px-[7px] text-left leading-[1.35] font-[560] text-[var(--text)] transition-colors duration-[var(--duration-fast)] ease-[var(--ease-standard)] hover:text-[var(--text)] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-2";
const pathOnly = (href: string) => href.split("#")[0];
const itemId = (item: SidebarNavigationItem, parent = "") =>
  `${parent}/${item.href ?? item.label}`;

function containsActive(item: SidebarNavigationItem, activeHref?: string): boolean {
  if (!activeHref) return false;
  return (
    (item.href ? pathOnly(item.href) === pathOnly(activeHref) : false) ||
    item.children?.some((child) => containsActive(child, activeHref)) === true
  );
}

function initialExpandedItems(
  items: SidebarNavigationItem[],
  activeHref?: string,
  parent = "",
) {
  const expanded = new Set<string>();

  for (const item of items) {
    const id = itemId(item, parent);
    if (item.children?.length && (item.defaultExpanded || containsActive(item, activeHref))) {
      expanded.add(id);
    }
    if (item.children) {
      for (const child of initialExpandedItems(item.children, activeHref, id)) {
        expanded.add(child);
      }
    }
  }

  return expanded;
}

function flattenItems(
  items: SidebarNavigationItem[],
  expanded: ReadonlySet<string>,
  depth = 1,
  parent = "",
): VisibleItem[] {
  return items.flatMap((item) => {
    const id = itemId(item, parent);
    return [
      { item, id, depth },
      ...(item.children?.length && expanded.has(id)
        ? flattenItems(item.children, expanded, depth + 1, id)
        : []),
    ];
  });
}

export function SidebarNavigation({
  groups,
  activeHref,
  ariaLabel = "Sidebar navigation",
  onActiveHrefChange,
  renderLink,
}: SidebarNavigationProps) {
  const LinkComponent = renderLink ?? "a";
  const reduceMotion = useReducedMotion() ?? false;
  const navigationRef = useRef<HTMLElement>(null);
  const selectedReady = useRef(false);
  const hoverVisible = useRef(false);
  const selectedX = useMotionValue(0);
  const selectedY = useMotionValue(0);
  const selectedWidth = useMotionValue(0);
  const selectedHeight = useMotionValue(0);
  const selectedOpacity = useMotionValue(0);
  const hoverX = useMotionValue(0);
  const hoverY = useMotionValue(0);
  const hoverWidth = useMotionValue(0);
  const hoverHeight = useMotionValue(0);
  const hoverOpacity = useMotionValue(0);
  const [layoutVersion, setLayoutVersion] = useState(0);
  const [expandedGroups, setExpandedGroups] = useState(
    () =>
      new Set(
        groups
          .filter(
            (group) =>
              group.defaultExpanded !== false ||
              group.items.some((item) => containsActive(item, activeHref)),
          )
          .map((group) => group.label),
      ),
  );
  const [expandedItems, setExpandedItems] = useState(() => {
    const expanded = new Set<string>();
    for (const group of groups) {
      for (const id of initialExpandedItems(group.items, activeHref, group.label)) {
        expanded.add(id);
      }
    }
    return expanded;
  });

  const toggleGroup = (label: string) => {
    setExpandedGroups((current) => {
      const next = new Set(current);
      if (next.has(label)) next.delete(label);
      else next.add(label);
      return next;
    });
  };

  const toggleItem = (id: string) => {
    setExpandedItems((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const measure = (element: HTMLElement) => {
    const navigation = navigationRef.current;
    if (!navigation) return null;
    const navigationRect = navigation.getBoundingClientRect();
    const elementRect = element.getBoundingClientRect();
    return {
      x: elementRect.left - navigationRect.left,
      y: elementRect.top - navigationRect.top,
      width: elementRect.width,
      height: elementRect.height,
    };
  };

  const moveHover = (element: HTMLElement) => {
    const target = measure(element);
    if (!target) return;
    const transition = reduceMotion ? still : motionTokens.spring.smooth;

    if (!hoverVisible.current || reduceMotion) {
      hoverX.jump(target.x);
      hoverY.jump(target.y);
      hoverWidth.jump(target.width);
      hoverHeight.jump(target.height);
    } else {
      animate(hoverX, target.x, transition);
      animate(hoverY, target.y, transition);
      animate(hoverWidth, target.width, transition);
      animate(hoverHeight, target.height, transition);
    }
    hoverVisible.current = true;
    animate(hoverOpacity, 1, { duration: reduceMotion ? 0 : 0.08 });
  };

  const hideHover = () => {
    hoverVisible.current = false;
    animate(hoverOpacity, 0, { duration: reduceMotion ? 0 : 0.08 });
  };

  useLayoutEffect(() => {
    const activePath = activeHref ? pathOnly(activeHref) : "";
    const activeItemIsVisible = groups.some(
      (group) =>
        expandedGroups.has(group.label) &&
        flattenItems(group.items, expandedItems, 1, group.label).some(
          ({ item }) =>
            !item.children?.length &&
            Boolean(item.href && pathOnly(item.href) === activePath),
        ),
    );

    if (!activeItemIsVisible) {
      selectedReady.current = false;
      selectedOpacity.jump(0);
      return;
    }

    const navigation = navigationRef.current;
    const selected = navigation?.querySelector<HTMLElement>(
      '[aria-current="page"]',
    );
    if (!selected) {
      selectedReady.current = false;
      selectedOpacity.jump(0);
      return;
    }

    const selectedRow = selected.closest<HTMLElement>(".sya-sidebar-row");
    if (
      selectedRow &&
      selectedRow.getBoundingClientRect().height < rowHeight - 0.5
    ) {
      selectedReady.current = false;
      selectedOpacity.jump(0);
      return;
    }

    const target = measure(selected);
    if (!target) return;
    const transition = reduceMotion ? still : motionTokens.spring.morph;

    if (!selectedReady.current || reduceMotion) {
      selectedX.jump(target.x);
      selectedY.jump(target.y);
      selectedWidth.jump(target.width);
      selectedHeight.jump(target.height);
    } else {
      animate(selectedX, target.x, transition);
      animate(selectedY, target.y, transition);
      animate(selectedWidth, target.width, transition);
      animate(selectedHeight, target.height, transition);
    }
    selectedReady.current = true;
    selectedOpacity.jump(1);
  }, [activeHref, expandedGroups, expandedItems, groups, layoutVersion, reduceMotion, selectedHeight, selectedOpacity, selectedWidth, selectedX, selectedY]);

  return (
    <nav
      ref={navigationRef}
      className="relative grid gap-1"
      aria-label={ariaLabel}
      onPointerLeave={hideHover}
    >
      <motion.span
        className="pointer-events-none absolute top-0 left-0 z-0 rounded-[7px] bg-[color-mix(in_srgb,var(--surface-muted)_72%,transparent)]"
        style={{
          x: hoverX,
          y: hoverY,
          width: hoverWidth,
          height: hoverHeight,
          opacity: hoverOpacity,
        }}
        aria-hidden="true"
      />
      <motion.span
        className="pointer-events-none absolute top-0 left-0 z-0 rounded-[7px] bg-[color-mix(in_srgb,var(--text)_7%,var(--surface-muted))]"
        style={{
          x: selectedX,
          y: selectedY,
          width: selectedWidth,
          height: selectedHeight,
          opacity: selectedOpacity,
        }}
        aria-hidden="true"
      />
        {groups.map((group) => {
          const groupOpen = expandedGroups.has(group.label);
          const panelId = `sidebar-${group.label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
          const visibleItems = groupOpen
            ? flattenItems(group.items, expandedItems, 1, group.label)
            : [];

          return (
            <section className="relative z-[1] min-w-0" key={group.label}>
              <button
                className={`${parentButtonClass} text-[11px] tracking-[0.055em] uppercase`}
                type="button"
                aria-expanded={groupOpen}
                aria-controls={panelId}
                onClick={() => toggleGroup(group.label)}
              >
                <span className="relative z-[1] min-w-0 overflow-hidden text-ellipsis whitespace-nowrap">{group.label}</span>
                <span className="relative z-[1] inline-flex min-w-0 items-center gap-[7px]">
                  {group.count !== undefined ? (
                    <span className="text-[11px] leading-none font-[560] tabular-nums text-[var(--text-secondary)]">{group.count}</span>
                  ) : null}
                  <motion.span
                    className="grid h-4 w-[13px] shrink-0 basis-[13px] place-items-center text-[var(--text-secondary)]"
                    initial={false}
                    animate={{ rotate: groupOpen ? 90 : 0 }}
                    transition={reduceMotion ? still : motionTokens.spring.snappy}
                    aria-hidden="true"
                  >
                    <ChevronRight size={13} />
                  </motion.span>
                </span>
              </button>

              <div className="my-[3px] mb-px min-w-0" id={panelId}>
                <AnimatePresence initial={false} mode="sync">
                  {visibleItems.map(({ item, id, depth }, index) => {
                    const hasChildren = Boolean(item.children?.length);
                    const itemOpen = hasChildren && expandedItems.has(id);
                    const active =
                      !hasChildren &&
                      Boolean(
                        item.href &&
                          activeHref &&
                          pathOnly(item.href) === pathOnly(activeHref),
                      );
                    const delay = Math.min(index, 7) * motionTokens.stagger.item;

                    return (
                      <motion.div
                        className="sya-sidebar-row relative flow-root h-[35px] min-w-0"
                        key={id}
                        initial={
                          reduceMotion
                            ? false
                            : { height: 0, opacity: 0, x: -6, overflow: "hidden" }
                        }
                        animate={{
                          height: rowHeight,
                          opacity: 1,
                          x: 0,
                          pointerEvents: "auto",
                          transitionEnd: { overflow: "visible" },
                          transition: reduceMotion
                            ? still
                            : {
                                height: motionTokens.spring.smooth,
                                opacity: {
                                  duration: motionTokens.duration.fast,
                                  ease: motionTokens.ease.enter,
                                  delay,
                                },
                                x: { ...motionTokens.spring.smooth, delay },
                              },
                        }}
                        exit={
                          reduceMotion
                            ? { opacity: 0, transition: still }
                            : {
                                height: 0,
                                opacity: 0,
                                x: -4,
                                overflow: "hidden",
                                pointerEvents: "none",
                                transition: {
                                  height: motionTokens.spring.smooth,
                                  opacity: {
                                    duration: motionTokens.duration.instant,
                                    ease: motionTokens.ease.standard,
                                  },
                                  x: {
                                    duration: motionTokens.duration.instant,
                                    ease: motionTokens.ease.standard,
                                  },
                                },
                            }
                        }
                        onAnimationComplete={() => {
                          if (active) setLayoutVersion((version) => version + 1);
                        }}
                      >
                        {!hasChildren && depth > 1 ? (
                          <span className="pointer-events-none absolute -top-px -bottom-px left-[13px] z-[2] w-px bg-[var(--border)]" aria-hidden="true" />
                        ) : null}
                        {hasChildren ? (
                          <button
                            className={`${parentButtonClass} text-[13px]`}
                            type="button"
                            aria-expanded={itemOpen}
                            onClick={() => toggleItem(id)}
                          >
                            <span className="relative z-[1] min-w-0 overflow-hidden text-ellipsis whitespace-nowrap">{item.label}</span>
                            <span className="relative z-[1] inline-flex min-w-0 items-center gap-[7px]">
                              {item.count !== undefined ? (
                                <span className="text-[11px] leading-none font-[560] tabular-nums text-[var(--text-secondary)]">{item.count}</span>
                              ) : null}
                              <motion.span
                                className="grid h-4 w-[13px] shrink-0 basis-[13px] place-items-center text-[var(--text-secondary)]"
                                initial={false}
                                animate={{ rotate: itemOpen ? 90 : 0 }}
                                transition={
                                  reduceMotion ? still : motionTokens.spring.snappy
                                }
                                aria-hidden="true"
                              >
                                <ChevronRight size={13} />
                              </motion.span>
                            </span>
                          </button>
                        ) : item.href ? (
                          <LinkComponent
                            className={["relative my-px ml-5 flex h-[33px] min-w-0 items-center rounded-[7px] px-[9px] text-[13px] leading-[1.35] no-underline transition-colors duration-[var(--duration-fast)] ease-[var(--ease-standard)] hover:text-[var(--text)] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-2", active ? "text-[var(--text)]" : "text-[var(--text-secondary)]"].join(" ")}
                            href={item.href}
                            aria-current={active ? "page" : undefined}
                            onClick={() => onActiveHrefChange?.(item.href!)}
                            onPointerEnter={(event) =>
                              moveHover(event.currentTarget)
                            }
                          >
                            <span className="relative z-[1] min-w-0 overflow-hidden text-ellipsis whitespace-nowrap">{item.label}</span>
                          </LinkComponent>
                        ) : null}
                      </motion.div>
                    );
                  })}
                </AnimatePresence>
              </div>
            </section>
          );
        })}
    </nav>
  );
}
